// server.js (versão com o jogo embutido) — servidor SEM dependências (só Node 16+). Serve o jogo e retransmite mensagens WebSocket entre anfitrião e jogadores.
// Uso:  node server.js   (porta 3000; mude com PORT=4000 node server.js)
const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto'),os=require('os');
const PORT=+process.env.PORT||3000,ROOT=__dirname,MAXC=4,GUID='258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
const MIME={'.html':'text/html;charset=utf-8','.js':'text/javascript;charset=utf-8','.css':'text/css;charset=utf-8','.json':'application/json','.png':'image/png','.ico':'image/x-icon'};
// Jogo embutido (gerado por make-deploy.js): não precisa das pastas css/ e js/.
const ASSETS={};for(const [p,t,b] of [["/index.html","text/html;charset=utf-8",""],["/css/style.css","text/css;charset=utf-8",""],["/js/ai.js","text/javascript;charset=utf-8",""],["/js/config.js","text/javascript;charset=utf-8",""],["/js/fnaf2.js","text/javascript;charset=utf-8",""],["/js/gfx.js","text/javascript;charset=utf-8",""],["/js/interact.js","text/javascript;charset=utf-8",""],["/js/loop.js","text/javascript;charset=utf-8",""],["/js/main.js","text/javascript;charset=utf-8","J3VzZSBzdHJpY3QnOwovLyA9PT09PSBJTsONQ0lPID09PT09Clc9bG9hZCgpO3JlYnVpbGQoKTtzcGF3blAoKTt1aSgpO3JlcXVlc3RBbmltYXRpb25GcmFtZShsb29wKTsK"],["/js/net.js","text/javascript;charset=utf-8",""],["/js/night.js","text/javascript;charset=utf-8",""],["/js/physics.js","text/javascript;charset=utf-8",""],["/js/render.js","text/javascript;charset=utf-8",""],["/js/systems.js","text/javascript;charset=utf-8",""],["/js/touch.js","text/javascript;charset=utf-8",""],["/js/ui.js","text/javascript;charset=utf-8",""],["/js/world.js","text/javascript;charset=utf-8",""]])ASSETS[p]={t,b:Buffer.from(b,'base64')};
const srv=http.createServer((q,r)=>{let u;try{u=decodeURIComponent(q.url.split('?')[0])}catch(e){u='/'}if(u==='/')u='/index.html';
 const a=ASSETS[u];if(!a){r.writeHead(404);return r.end('404')}r.writeHead(200,{'Content-Type':a.t,'Cache-Control':'no-store'});r.end(a.b)});
// ----- WebSocket mínimo (RFC 6455): texto, ping/pong, close
function frame(op,data){const p=Buffer.from(data),n=p.length;let h;if(n<126)h=Buffer.from([0x80|op,n]);else if(n<65536){h=Buffer.alloc(4);h[0]=0x80|op;h[1]=126;h.writeUInt16BE(n,2)}else{h=Buffer.alloc(10);h[0]=0x80|op;h[1]=127;h.writeBigUInt64BE(BigInt(n),2)}return Buffer.concat([h,p])}
const send=(c,o)=>{if(c&&!c.s.destroyed)c.s.write(frame(1,JSON.stringify(o)))};
function parse(c){for(;;){const b=c.buf;if(b.length<2)return;let n=b[1]&127,o=2;
 if(n===126){if(b.length<4)return;n=b.readUInt16BE(2);o=4}else if(n===127){if(b.length<10)return;n=Number(b.readBigUInt64BE(2));o=10}
 const mk=(b[1]&128)!==0;if(mk)o+=4;if(n>(1<<20))return c.s.destroy();if(b.length<o+n)return;
 let p=Buffer.from(b.subarray(o,o+n));if(mk){const k=b.subarray(o-4,o);for(let i=0;i<n;i++)p[i]^=k[i&3]}
 const op=b[0]&15;c.buf=b.subarray(o+n);
 if(op===8){c.s.end(frame(8,''));return}if(op===9)c.s.write(frame(10,p));else if(op===1){let j;try{j=JSON.parse(p.toString())}catch(e){continue}msg(c,j)}}}
srv.on('upgrade',(q,s)=>{if(q.url.split('?')[0]!=='/ws'||!q.headers['sec-websocket-key'])return s.destroy();
 s.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+crypto.createHash('sha1').update(q.headers['sec-websocket-key']+GUID).digest('base64')+'\r\n\r\n');
 s.setNoDelay(true);const c={s,buf:Buffer.alloc(0),id:0,host:false,dead:false};
 s.on('data',d=>{c.buf=Buffer.concat([c.buf,d]);parse(c)});s.on('close',()=>drop(c));s.on('error',()=>drop(c))});
// ----- sala única: 1 anfitrião + até 4 jogadores
let host=null,nid=1;const cl=new Map();
const ips=()=>Object.values(os.networkInterfaces()).flat().filter(i=>i&&i.family==='IPv4'&&!i.internal).map(i=>i.address);
function msg(c,m){
 if(m.t==='host'){if(host&&host!==c)return send(c,{t:'busy'});host=c;c.host=true;return send(c,{t:'hosted',ips:ips(),port:PORT})}
 if(m.t==='join'){if(c.host||c.id)return;if(!host)return send(c,{t:'nohost'});if(cl.size>=MAXC)return send(c,{t:'full'});
  c.id=nid++;cl.set(c.id,c);send(c,{t:'welcome',id:c.id});return send(host,{t:'join',id:c.id})}
 if(c.host){if(m.to)send(cl.get(m.to),m);else for(const x of cl.values())send(x,m)}
 else if(c.id&&host){m.from=c.id;send(host,m)}}
function drop(c){if(c.dead)return;c.dead=true;
 if(c===host){host=null;for(const x of cl.values()){send(x,{t:'hostleft'});x.s.end()}cl.clear()}
 else if(c.id){cl.delete(c.id);send(host,{t:'leave',id:c.id})}}
if(require.main===module)srv.listen(PORT,'0.0.0.0',()=>{console.log('\n  Night Shift Builder — servidor LAN\n');console.log('  Anfitrião:  http://localhost:'+PORT);ips().forEach(i=>console.log('  Jogadores:  http://'+i+':'+PORT));
 console.log('\n  Se ninguém conseguir entrar, libere a porta '+PORT+' no firewall do anfitrião.\n')});
module.exports=srv;
